<?php require '../config/auth.php';login_required('admin');$page_title='Students';$q=trim($_GET['q']??'');$sql='SELECT s.*,u.email,u.status user_status FROM students s JOIN users u ON u.id=s.user_id';$p=[];if($q){$sql.=' WHERE s.full_name LIKE ? OR s.roll_number LIKE ? OR s.department LIKE ? OR u.email LIKE ?';$p=array_fill(0,4,"%$q%");}$sql.=' ORDER BY s.created_at DESC';$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();require '../config/header.php';?><div class="head"><div><h1>Student Management</h1><p>Search and review registered students.</p></div></div><form class="search"><input class="control" name="q" value="<?=e($q)?>" placeholder="Name, roll number, department or email"><button class="btn primary">Search</button></form><div class="card tablewrap"><table class="table"><tr><th>Name</th><th>Email</th><th>Course</th><th>Department</th><th>CGPA</th><th>Status</th><th>Resume</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['course'])?></td><td><?=e($r['department'])?></td><td><?=e($r['cgpa'])?></td><td><span class="badge green"><?=e($r['user_status'])?></span></td><td><?php if($r['resume']):?><a class="btn outline sm" target="_blank" href="../<?=e($r['resume'])?>">View</a><?php endif;?></td></tr><?php endforeach;?></table></div><?php require '../config/footer.php';?>
